#!/usr/bin/env node
'use strict';

/**
 * A local, dependency-free evidence layer for knowledge-init.
 *
 * It deliberately does not generate prose.  It makes the inputs and the
 * freshness of prose generated by an Agent auditable: source fingerprints,
 * detected symbols/entrypoints, affected pages, validation, and small cards.
 */
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const childProcess = require('child_process');

const ENGINE_VERSION = '0.4.0';
const DEFAULT_IGNORES = new Set([
  '.git', '.aisdd', 'node_modules', 'dist', 'build', 'target', 'coverage',
  '.next', '.venv', 'venv', '__pycache__', '.idea', '.vscode', 'vendor',
  '.claude', '.codex', '.cursor', '.qoder', '.catpaw',
]);
const SENSITIVE_PATH = /(^|\/)(\.env(?:\..*)?|.*(?:secret|credential|private[_-]?key|id_rsa).*)(?:$|\/)/i;
const TEXT_EXTENSIONS = new Set([
  '.c', '.cc', '.cpp', '.cs', '.go', '.h', '.hpp', '.java', '.js', '.jsx',
  '.kt', '.kts', '.mjs', '.py', '.rb', '.rs', '.scala', '.sh', '.sql', '.ts',
  '.tsx', '.vue', '.xml', '.yaml', '.yml', '.json', '.proto', '.gradle', '.cjs',
  '.php', '.swift', '.dart', '.lua', '.ex', '.exs', '.pl',
  '.md', '.mdx', '.rst', '.txt', '.adoc',
  '.properties', '.toml', '.ini', '.cfg', '.conf', '.mod', '.sum',
  '.html', '.htm', '.css', '.scss', '.less', '.tf', '.j2', '.tpl',
]);
const SPECIAL_FILENAMES = new Set([
  'dockerfile', 'makefile', 'gemfile', 'procfile', 'jenkinsfile', 'vagrantfile', 'brewfile', 'justfile',
]);
const MAX_FILE_BYTES = 1024 * 1024;

function fail(message) { process.stderr.write(`knowledge-engine: ${message}\n`); process.exitCode = 1; }
function sha256(buffer) { return crypto.createHash('sha256').update(buffer).digest('hex'); }
function toPosix(value) { return value.split(path.sep).join('/'); }
function now() { return new Date().toISOString(); }
function engineDir(root) { return path.join(root, '.aisdd', 'knowledges', '.engine'); }
function manifestPath(root) { return path.join(engineDir(root), 'manifest.json'); }
function cardsPath(root) { return path.join(engineDir(root), 'cards.json'); }
function embeddingsPath(root) { return path.join(engineDir(root), 'embeddings.json'); }
function impactPath(root) { return path.join(engineDir(root), 'impact-report.json'); }
function serviceMapPath(root) { return path.join(root, '.aisdd', 'knowledges', 'service-map.json'); }
function runtimeHtmlPath(root) { return path.join(root, '.aisdd', 'knowledges', 'visualizations', 'service-runtime-map.html'); }
function updateRecordPath(root) { return path.join(engineDir(root), 'update-record.json'); }

function parseArgs(argv) {
  const values = { command: argv[2] || 'help', root: '.', dryRun: false, out: null, query: null, language: null, force: false };
  for (let index = 3; index < argv.length; index += 1) {
    const token = argv[index];
    if (token === '--dry-run') values.dryRun = true;
    else if (token === '--out') values.out = argv[++index];
    else if (token === '--query') values.query = argv[++index];
    else if (token === '--language') values.language = argv[++index];
    else if (token === '--force') values.force = true;
    else if (!token.startsWith('-') && values.root === '.') values.root = token;
    else throw new Error(`unknown argument: ${token}`);
  }
  values.root = path.resolve(values.root);
  return values;
}

function git(root, args) {
  try { return childProcess.execFileSync('git', ['-C', root, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim(); }
  catch (_) { return null; }
}

function gitState(root) {
  if (git(root, ['--version']) === null) return 'no-git';
  if (git(root, ['rev-parse', '--is-inside-work-tree']) !== 'true') return 'no-git';
  return git(root, ['rev-parse', 'HEAD']) ? 'ok' : 'no-commits';
}

function readGitContext(root) {
  const head = git(root, ['rev-parse', 'HEAD']);
  if (!head) return null;
  const recentCommits = (git(root, ['log', '-n', '20', '--date=short', '--pretty=format:%H%x1f%ad%x1f%an%x1f%s']) || '')
    .split('\n').filter(Boolean).map((line) => {
      const [sha, date, author, subject] = line.split('\x1f');
      return { sha, date, author, subject };
    });
  const branches = (git(root, ['for-each-ref', '--format=%(refname:short)%x1f%(objectname)', 'refs/heads']) || '')
    .split('\n').filter(Boolean).map((line) => { const [name, sha] = line.split('\x1f'); return { name, sha }; });
  const tags = (git(root, ['tag', '--points-at', 'HEAD']) || '').split('\n').filter(Boolean);
  const remotes = (git(root, ['remote', '-v']) || '').split('\n').filter(Boolean)
    .map((line) => { const [name, url, kind] = line.split(/\s+/); return { name, url, kind: (kind || '').replace(/[()]/g, '') }; });
  return {
    head, branch: git(root, ['branch', '--show-current']) || null,
    headTags: tags, branches, remotes, recentCommits,
    worktree: { porcelain: (git(root, ['status', '--porcelain']) || '').split('\n').filter(Boolean) },
  };
}

function readScope(root) {
  const plan = path.join(root, '.aisdd', 'knowledges', 'wiki_plan.yaml');
  if (!fs.existsSync(plan)) return { include: [], exclude: [] };
  const empty = { include: [], exclude: [] };
  const lines = fs.readFileSync(plan, 'utf8').split(/\r?\n/);
  const start = lines.findIndex((line) => /^scope:\s*$/.test(line));
  if (start === -1) return empty;
  const block = [];
  for (let index = start + 1; index < lines.length; index += 1) {
    const line = lines[index];
    if (line.trim() && !/^[ \t]/.test(line)) break;
    block.push(line);
  }
  const strip = (value) => value.trim().replace(/^['"]|['"]$/g, '');
  const list = (name) => {
    const keyIndex = block.findIndex((line) => new RegExp(`^[ \\t]*${name}:[ \\t]*`).test(line));
    if (keyIndex === -1) return [];
    const inline = block[keyIndex].match(/^[ \t]*[\w-]+:[ \t]*\[(.*)\][ \t]*$/);
    if (inline) return inline[1].split(',').map(strip).filter(Boolean);
    const indent = block[keyIndex].match(/^[ \t]*/)[0].length;
    const items = [];
    for (let index = keyIndex + 1; index < block.length; index += 1) {
      const line = block[index];
      if (!line.trim()) continue;
      if (line.match(/^[ \t]*/)[0].length <= indent) break;
      const item = line.match(/^[ \t]*-[ \t]*(.+?)[ \t]*$/);
      if (item) items.push(strip(item[1]));
    }
    return items.filter(Boolean);
  };
  return { include: list('include'), exclude: list('exclude') };
}

function globMatches(pattern, candidate) {
  const escaped = pattern.split('**').map((part) => part.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '[^/]*')).join('.*');
  return new RegExp(`^${escaped}$`).test(candidate);
}

/**
 * .gitignore 语义子集：无 `/` 的模式按名字匹配任意层级；含 `/` 或开头 `/` 锚定项目根；
 * 结尾 `/` 仅目录；`**` 跨零或多个路径段；`!` 反向豁免（exclude 内最后命中者生效）。
 * 不支持花括号展开、字符类与转义。
 */
function compileIgnoreRule(pattern) {
  let body = String(pattern).trim();
  if (!body) return null;
  let negate = false;
  if (body.startsWith('!')) { negate = true; body = body.slice(1); }
  const dirOnly = body.endsWith('/');
  body = body.replace(/\/+$/, '');
  if (!body) return null;
  const anchored = body.startsWith('/') || body.includes('/', 1);
  body = body.replace(/^\/+/, '');
  const segments = body.split('/').map((segment) => segment.trim()).filter(Boolean);
  if (!segments.length) return null;
  let source = '';
  let needsSlash = false;
  for (let index = 0; index < segments.length; index += 1) {
    const segment = segments[index];
    if (segment === '**') {
      const last = index === segments.length - 1;
      if (last) source += needsSlash ? '(?:/.*)?' : '.*';
      else source += needsSlash ? '/(?:[^/]*/)*' : '(?:[^/]*/)*';
      needsSlash = false;
      continue;
    }
    const escaped = segment.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '[^/]*').replace(/\?/g, '[^/]');
    source += (needsSlash ? '/' : '') + escaped;
    needsSlash = true;
  }
  return { pattern, negate, dirOnly, re: new RegExp(`^${anchored || source.startsWith('(') ? '' : '(?:[^/]*/)*'}${source}$`) };
}

const ruleCache = new Map();

function compiledRules(patterns) {
  const key = patterns.join('\u0001');
  if (!ruleCache.has(key)) ruleCache.set(key, patterns.map(compileIgnoreRule).filter(Boolean));
  return ruleCache.get(key);
}

function ruleHits(rule, relativePath) {
  const segments = relativePath.split('/');
  const limit = rule.dirOnly ? segments.length - 1 : segments.length;
  for (let index = 1; index <= limit; index += 1) if (rule.re.test(segments.slice(0, index).join('/'))) return true;
  return false;
}

function isInScope(relativePath, scope) {
  if (scope.include.length && !compiledRules(scope.include).some((rule) => !rule.negate && ruleHits(rule, relativePath))) return false;
  let excluded = false;
  for (const rule of compiledRules(scope.exclude)) if (ruleHits(rule, relativePath)) excluded = !rule.negate;
  return !excluded;
}

function walk(root, relative = '', scope = readScope(root)) {
  const absolute = path.join(root, relative);
  const results = [];
  for (const item of fs.readdirSync(absolute, { withFileTypes: true })) {
    const rel = path.join(relative, item.name);
    const normalized = toPosix(rel);
    if (SENSITIVE_PATH.test(normalized)) continue;
    if (item.isDirectory()) {
      if (!DEFAULT_IGNORES.has(item.name)) results.push(...walk(root, rel, scope));
    } else if (item.isFile()) {
      const ext = path.extname(item.name).toLowerCase();
      const isText = TEXT_EXTENSIONS.has(ext) || SPECIAL_FILENAMES.has(item.name.toLowerCase());
      const stat = fs.statSync(path.join(root, rel));
      if (isText && stat.size <= MAX_FILE_BYTES && isInScope(normalized, scope)) results.push(normalized);
    }
  }
  return results.sort();
}

function lineAt(content, index) { return content.slice(0, index).split('\n').length; }

function isCommentedAt(content, index) {
  const lineStart = content.lastIndexOf('\n', index) + 1;
  const before = content.slice(lineStart, index).trimStart();
  return before.startsWith('//') || before.startsWith('*') || before.startsWith('/*');
}

function joinBasePath(prefix, value) {
  const base = String(prefix || '').replace(/\/+$/, '');
  const tail = String(value || '').replace(/^\/+/, '').replace(/\/+$/, '');
  const joined = `${base}/${tail}`.replace(/\/{2,}/g, '/');
  return joined.startsWith('/') ? joined : `/${joined}`;
}

function firstQuoted(args, content) {
  const source = args === undefined ? content : args;
  const named = source.match(/(?:value|path)\s*=\s*(?:\{\s*)?["']([^"']*)["']/);
  if (named) return named[1];
  if (args !== undefined && /=/.test(args)) return '';
  const plain = source.match(/["']([^"']*)["']/);
  return plain ? plain[1] : '';
}

const SPRING_METHODS = { Get: 'GET', Post: 'POST', Put: 'PUT', Delete: 'DELETE', Patch: 'PATCH' };

/** Static HTTP routes per file. Comment-only matches, `${...}` placeholders and unresolved attrs are reported explicitly, never dropped. */
function httpRoutes(relativePath, content) {
  const routes = [];
  const lower = relativePath.toLowerCase();
  const push = (method, rawPath, index) => {
    if (isCommentedAt(content, index)) return;
    const value = String(rawPath || '');
    if (/\$\{|\{\}/.test(value)) { routes.push({ method, path: value, line: lineAt(content, index), unresolved: true }); return; }
    routes.push({ method, path: value === '' ? '' : joinBasePath('', value), line: lineAt(content, index) });
  };
  if (/\.(java|kt|kts)$/i.test(relativePath)) {
    const classIndex = (content.match(/\b(?:class|interface|object|enum)\s+[A-Za-z_$][\w$]*/) || {}).index;
    let prefix = null;
    const requestRe = /@RequestMapping\b(?:\s*\(([^)]*)\))?/g;
    let match;
    while ((match = requestRe.exec(content))) {
      if (isCommentedAt(content, match.index)) continue;
      const value = firstQuoted(match[1], '');
      if (prefix === null && classIndex !== undefined && match.index < classIndex) { prefix = value; continue; }
      const index = match.index;
      const line = lineAt(content, index);
      if (/\$\{|\{\}/.test(value)) { routes.push({ method: 'ANY', path: value, line, unresolved: true }); continue; }
      routes.push({ method: 'ANY', path: joinBasePath(prefix || '', value), line });
    }
    prefix = prefix || '';
    const springRe = /@(Get|Post|Put|Delete|Patch)Mapping\b(?:\s*\(([^)]*)\))?/g;
    while ((match = springRe.exec(content))) {
      if (isCommentedAt(content, match.index)) continue;
      const value = firstQuoted(match[2], '');
      const line = lineAt(content, match.index);
      const method = SPRING_METHODS[match[1]];
      if (/\$\{|\{\}/.test(value)) { routes.push({ method, path: value, line, unresolved: true }); continue; }
      routes.push({ method, path: joinBasePath(prefix, value), line });
    }
    return routes;
  }
  const decorators = [
    { re: /\b(?:app|router|api|bp|blueprint)\.(get|post|put|delete|patch)\s*\(\s*['"`]([^'"`]*)['"`]/gi, test: () => /\.(js|jsx|ts|tsx|mjs|cjs|vue|py)$/i.test(lower), method: (m) => m[1].toUpperCase() },
    { re: /@(Get|Post|Put|Delete|Patch)\s*\(\s*['"]([^'"]*)['"]/g, test: () => /\.(ts|js)$/i.test(lower), method: (m) => SPRING_METHODS[m[1]] },
    { re: /\b[\w.]+\.(GET|POST|PUT|DELETE|PATCH)\s*\(\s*["']([^"']*)["']/g, test: () => /\.go$/i.test(lower), method: (m) => m[1] },
    { re: /#\[(get|post|put|delete|patch)\s*\(\s*["']([^"']*)/gi, test: () => /\.rs$/i.test(lower), method: (m) => m[1].toUpperCase() },
    { re: /\bRoute::\s*(get|post|put|delete|patch|any)\s*\(\s*['"]([^'"]*)['"]/gi, test: () => /\.php$/i.test(lower), method: (m) => m[1].toUpperCase() },
  ];
  for (const decorator of decorators) {
    if (!decorator.test()) continue;
    let match;
    while ((match = decorator.re.exec(content))) {
      if (isCommentedAt(content, match.index)) continue;
      const value = match[2];
      const line = lineAt(content, match.index);
      if (/\$\{|\{\}|%s|\{\}/.test(value)) { routes.push({ method: decorator.method(match), path: value, line, unresolved: true }); continue; }
      routes.push({ method: decorator.method(match), path: joinBasePath('', value), line });
    }
  }
  return routes;
}

function messagingEntrypoints(relativePath, content) {
  const found = [];
  const lower = relativePath.toLowerCase();
  const scan = (regex, kind, group = 1) => {
    let match;
    while ((match = regex.exec(content))) {
      if (isCommentedAt(content, match.index)) continue;
      if (match[group]) found.push({ kind, value: match[group], line: lineAt(content, match.index) });
    }
  };
  if (/\.(java|kt|kts)$/i.test(lower)) {
    scan(/@KafkaListener\b\s*\((?:[^)]*)?(?:topics|topicPattern)\s*=\s*(?:\{\s*)?["']([^"']+)/g, 'mq-consumer');
    scan(/@RabbitListener\b\s*\((?:[^)]*)?(?:queues|queuesToDeclare|value)?\s*(?:\{\s*)?["']([^"']+)/g, 'mq-consumer');
    scan(/@RocketMQMessageListener\b\s*\([^)]*topic\s*=\s*["']([^"']+)/g, 'mq-consumer');
    scan(/(?:KafkaTemplate|RabbitTemplate|RocketMQTemplate)\w*\s*\.\s*(?:send|sendAsync|convertAndSend|publish)\w*\s*\(\s*["']([^"']+)/g, 'mq-producer');
    scan(/@(?:Grpc|Dubbo)Service\b[^\n]*\n[^\n]*\b(?:class|interface)\s+([A-Za-z_$][\w$]*)/g, 'rpc');
    scan(/@(?:Transactional)?EventListener\b[^\n]*\n[^\n]*\b([A-Za-z_$][\w$]*)\s*\(/g, 'event-listener');
  }
  if (/\.(js|ts|py|go)$/i.test(lower)) {
    scan(/(?:producer|publisher)\s*\.\s*(?:send|publish)\s*\(\s*["']([^"']+)/g, 'mq-producer');
    scan(/\bconsumer\s*\.\s*(?:subscribe|on)\s*\(\s*["']([^"']+)/g, 'mq-consumer');
    scan(/@(?:on_event|event)\s*\(\s*["']([^"']+)/g, 'event-listener');
  }
  if (/\.proto$/i.test(lower)) {
    scan(/^\s*service\s+([A-Za-z_$][\w$]*)/gm, 'rpc');
    scan(/^\s*rpc\s+([A-Za-z_$][\w$]*)\s*\(/gm, 'rpc-method');
  }
  return found;
}

function extractFacts(relativePath, content) {
  const symbols = [];
  const entrypoints = [];
  const dependencies = [];
  const addSymbols = (regex, kind) => {
    let match;
    while ((match = regex.exec(content))) symbols.push({ name: match[1], kind, line: lineAt(content, match.index) });
  };
  addSymbols(/\b(?:class|interface|enum|record)\s+([A-Za-z_$][\w$]*)/g, 'type');
  addSymbols(/\b(?:function|def|func)\s+([A-Za-z_$][\w$]*)/g, 'function');
  addSymbols(/\b(?:public|private|protected)\s+(?:static\s+)?[\w<>\[\], ?]+\s+([A-Za-z_$][\w$]*)\s*\(/g, 'method');
  const routes = httpRoutes(relativePath, content);
  for (const route of routes) entrypoints.push({ kind: 'http', value: `${route.method} ${route.path}${route.unresolved ? ' (unresolved)' : ''}`, line: route.line });
  const scheduledRe = /@Scheduled\b\s*\((?:[^)]*)?(?:cron|fixedRate|fixedDelay)\s*=\s*["']?([^"')]+)/g;
  let scheduled;
  while ((scheduled = scheduledRe.exec(content))) if (!isCommentedAt(content, scheduled.index)) entrypoints.push({ kind: 'scheduled', value: scheduled[1], line: lineAt(content, scheduled.index) });
  for (const found of messagingEntrypoints(relativePath, content)) entrypoints.push(found);
  const addDependencies = (regex) => {
    let match;
    while ((match = regex.exec(content))) dependencies.push(match[1]);
  };
  addDependencies(/^\s*import\s+(?:.+?\s+from\s+)?["']([^"']+)["']/gm); // JS/TS
  addDependencies(/^\s*import\s+([\w.]+)/gm); // Java/Python
  addDependencies(/^\s*from\s+([\w.]+)/gm); // Python
  addDependencies(/^\s*import\s+\(?\s*([\w./-]+)/gm); // Go
  return { symbols: symbols.slice(0, 250), entrypoints: entrypoints.slice(0, 400), routes: routes.slice(0, 400), dependencies: [...new Set(dependencies)].slice(0, 250) };
}

function collectHttpRoutes(root) {
  const routes = [];
  for (const relativePath of walk(root)) {
    const absolute = path.join(root, relativePath);
    let content;
    try { content = fs.readFileSync(absolute, 'utf8'); } catch { continue; }
    for (const route of httpRoutes(relativePath, content)) routes.push({ ...route, file: relativePath });
  }
  return routes;
}

function parseFrontmatter(markdown) {
  const match = markdown.match(/^---\s*\n([\s\S]*?)\n---\s*\n?/);
  if (!match) return null;
  const fields = {};
  for (const line of match[1].split('\n')) {
    const found = line.match(/^([A-Za-z_][\w-]*):\s*(.*)$/);
    if (found) fields[found[1]] = found[2].trim().replace(/^['"]|['"]$/g, '');
  }
  return fields;
}

function scanKnowledgeDocs(root) {
  const knowledgeRoot = path.join(root, '.aisdd', 'knowledges');
  if (!fs.existsSync(knowledgeRoot)) return [];
  const docs = [];
  const visit = (dir) => {
    for (const item of fs.readdirSync(dir, { withFileTypes: true })) {
      if (item.name === '.engine') continue;
      const full = path.join(dir, item.name);
      if (item.isDirectory()) visit(full);
      else if (item.isFile() && item.name.endsWith('.md')) {
        const body = fs.readFileSync(full, 'utf8');
        const meta = parseFrontmatter(body);
        if (meta) docs.push({ path: toPosix(path.relative(root, full)), meta, body });
      }
    }
  };
  visit(knowledgeRoot);
  return docs;
}

function buildManifest(root) {
  if (!fs.existsSync(root) || !fs.statSync(root).isDirectory()) throw new Error(`root does not exist: ${root}`);
  const scope = readScope(root);
  const files = walk(root, '', scope).map((relativePath) => {
    const content = fs.readFileSync(path.join(root, relativePath));
    const text = content.toString('utf8');
    const facts = extractFacts(relativePath, text);
    return { path: relativePath, sha256: sha256(content), bytes: content.length, ...facts };
  });
  return {
    schemaVersion: 2, engineVersion: ENGINE_VERSION, generatedAt: now(), root, gitState: gitState(root), git: readGitContext(root), scope, files,
    documents: scanKnowledgeDocs(root).map(({ path: docPath, meta }) => ({ path: docPath, uuid: meta.uuid || null, type: meta.type || null, sourceFiles: parseSourceFiles(meta.source_files) })),
  };
}

function parseSourceFiles(value) {
  if (!value) return [];
  if (value.startsWith('[') && value.endsWith(']')) {
    return value.slice(1, -1).split(',').map((v) => v.trim().replace(/^['"]|['"]$/g, '')).filter(Boolean);
  }
  return [value.replace(/^['"]|['"]$/g, '')];
}

function writeJson(target, data, dryRun) {
  if (dryRun) { process.stdout.write(`[dry-run] would write ${target}\n`); return; }
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, `${JSON.stringify(data, null, 2)}\n`, 'utf8');
  process.stdout.write(`wrote ${target}\n`);
}

function writeText(target, content, dryRun) {
  if (dryRun) { process.stdout.write(`[dry-run] would write ${target}\n`); return; }
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content, 'utf8');
  process.stdout.write(`wrote ${target}\n`);
}

function loadManifest(root) {
  const target = manifestPath(root);
  if (!fs.existsSync(target)) throw new Error(`manifest not found; run scan first: ${target}`);
  return JSON.parse(fs.readFileSync(target, 'utf8'));
}

function matchesTouchedSource(source, touchedSet, touchedList) {
  if (touchedSet.has(source)) return 'exact';
  if (source.includes('*') || source.includes('?')) return touchedList.some((file) => globMatches(source, file)) ? 'glob' : null;
  const base = source.replace(/\/+$/, '');
  return touchedList.some((file) => file.startsWith(`${base}/`)) ? 'prefix' : null;
}

/** 端点/入口事实（HTTP 路由 + MQ/RPC/定时/事件）与符号事实的稳定标识，不含行号。 */
function factKeys(file) {
  const endpoints = new Set();
  const symbols = new Set();
  for (const route of (file && file.routes) || []) endpoints.add(`ROUTE ${route.method} ${route.path}${route.unresolved ? ' (unresolved)' : ''}`);
  for (const entry of (file && file.entrypoints) || []) if (entry.kind !== 'http') endpoints.add(`${String(entry.kind).toUpperCase()} ${entry.value}`);
  for (const symbol of (file && file.symbols) || []) symbols.add(`${symbol.kind} ${symbol.name}`);
  return { endpoints, symbols };
}

function diffFactSet(beforeFile, afterFile, key) {
  const beforeSet = factKeys(beforeFile)[key];
  const afterSet = factKeys(afterFile)[key];
  return {
    added: [...afterSet].filter((item) => !beforeSet.has(item)).sort(),
    removed: [...beforeSet].filter((item) => !afterSet.has(item)).sort(),
  };
}

function diffManifest(previous, current) {
  const before = new Map(previous.files.map((file) => [file.path, file]));
  const after = new Map(current.files.map((file) => [file.path, file]));
  const added = []; const changed = []; const deleted = [];
  for (const [filePath, file] of after) (!before.has(filePath) ? added : before.get(filePath).sha256 !== file.sha256 ? changed : []).push(filePath);
  for (const filePath of before.keys()) if (!after.has(filePath)) deleted.push(filePath);
  const touched = new Set([...added, ...changed, ...deleted]);
  const touchedList = [...touched];
  const factChanges = [...touched].sort().map((filePath) => {
    const endpoints = diffFactSet(before.get(filePath), after.get(filePath), 'endpoints');
    const symbols = diffFactSet(before.get(filePath), after.get(filePath), 'symbols');
    return endpoints.added.length || endpoints.removed.length || symbols.added.length || symbols.removed.length ? { file: filePath, endpoints, symbols } : null;
  }).filter(Boolean);
  const affected = current.documents.map((doc) => {
    const matched = doc.sourceFiles.map((source) => ({ source, reason: matchesTouchedSource(source, touched, touchedList) })).filter((item) => item.reason);
    return matched.length ? { path: doc.path, uuid: doc.uuid, type: doc.type, matchedBy: matched } : null;
  }).filter(Boolean);
  const endpointDelta = factChanges.reduce((total, item) => total + item.endpoints.added.length + item.endpoints.removed.length, 0);
  return {
    added, changed, deleted, factChanges, affectedDocuments: affected,
    requiresLedgerUpdate: endpointDelta > 0,
    requiresRegeneration: affected.length > 0 || added.length > 0 || deleted.length > 0,
  };
}

const HTTP_METHOD_IN_TEXT = /(GET|POST|PUT|DELETE|PATCH|ANY)/;

function normalizeEntry(method, target) {
  return `${String(method).toUpperCase()} /${String(target || '').replace(/^\/+/, '').replace(/\/+$/, '')}`;
}

/** 契约页的 `### {METHOD} {path}` 小节（机器对账用的稳定标识来源）。 */
function contractEntries(doc) {
  return [...doc.body.matchAll(/^#{2,4}\s+(GET|POST|PUT|DELETE|PATCH|ANY)\s+(\S+)(?:\s+-\s+.*)?$/gm)].map((found) => ({ method: found[1], path: found[2] }));
}

/** 多语言对账：语言页必须以主树页面为唯一事实来源，且结构与主树一致。 */
function checkTranslations(docs) {
  const errors = [];
  const warnings = [];
  const byPath = new Map(docs.map((doc) => [doc.path, doc]));
  const languageDocs = docs.filter((doc) => doc.meta.content_language);
  const summary = { languages: [...new Set(languageDocs.map((doc) => doc.meta.content_language))].sort(), pages: languageDocs.length, pending: 0, done: 0, mismatches: 0 };
  const uuidIndex = new Map();
  for (const doc of docs) { if (!doc.meta.uuid) continue; uuidIndex.set(doc.meta.uuid, (uuidIndex.get(doc.meta.uuid) || []).concat(doc.path)); }
  for (const [uuid, paths] of [...uuidIndex].filter(([, list]) => list.length > 1).sort()) errors.push(`uuid 重复: ${uuid} 出现在 ${paths.join(', ')}（语言页 uuid 须由 language-init 追加语言后缀）`);
  const headings = (body) => (body.match(/^###\s/gm) || []).length;
  for (const doc of languageDocs) {
    const state = doc.meta.translation_status;
    if (state === 'pending') summary.pending += 1;
    else if (state === 'done') summary.done += 1;
    else errors.push(`${doc.path}: 语言页必须声明 translation_status（pending / done），当前 ${state || '缺失'}`);
    if (!doc.meta.source_document) { errors.push(`${doc.path}: 语言页必须声明 source_document 指向主树页面`); continue; }
    const source = byPath.get(`.aisdd/knowledges/${toPosix(doc.meta.source_document)}`);
    if (!source) { errors.push(`${doc.path}: source_document 指向不存在的主树页面: ${doc.meta.source_document}`); continue; }
    if (source.meta.content_language) { errors.push(`${doc.path}: source_document 指向的是语言页 ${doc.meta.source_document}，必须指向无 content_language 的主树页面`); continue; }
    if (state === 'pending' && doc.meta.status !== 'stale') errors.push(`${doc.path}: translation_status 为 pending 时 status 必须为 stale（未完成的翻译不得宣称可用）`);
    if (state === 'done' && source.meta.status === 'stale') { summary.mismatches += 1; errors.push(`${doc.path}: 标记 done 但主树 ${doc.meta.source_document} 仍为 stale，须先更新主树再翻译`); }
    if (headings(source.body) !== headings(doc.body)) { summary.mismatches += 1; errors.push(`${doc.path}: \`###\` 小节数 ${headings(doc.body)} 与主树 ${headings(source.body)} 不一致（翻译不得增删小节）`); }
    if (source.meta.type === 'tech.api.contract') {
      const declared = Number(doc.meta.entry_count);
      if (!Number.isFinite(declared) || declared !== Number(source.meta.entry_count)) { summary.mismatches += 1; errors.push(`${doc.path}: entry_count 须与主树相同（主树 ${source.meta.entry_count}，本页 ${doc.meta.entry_count || '缺失'}）`); }
      const sourceKeys = new Set(contractEntries(source).map((entry) => normalizeEntry(entry.method, entry.path)));
      const targetKeys = new Set(contractEntries(doc).map((entry) => normalizeEntry(entry.method, entry.path)));
      const missing = [...sourceKeys].filter((key) => !targetKeys.has(key)).slice(0, 5);
      const extra = [...targetKeys].filter((key) => !sourceKeys.has(key)).slice(0, 5);
      if (missing.length || extra.length) { summary.mismatches += 1; errors.push(`${doc.path}: 契约小节与主树不等：缺少 ${missing.join(', ') || '无'}；多出（METHOD 与 path 不得翻译）${extra.join(', ') || '无'}`); }
    }
  }
  return { errors, warnings, summary };
}

/** 接口文档完整性对账：静态路由为分母；静态扫描为 0 时只接受人工声明分母（denominator: manual）的台账。 */
function checkContractCoverage(root, docs, routes) {
  const errors = [];
  const warnings = [];
  const canonical = docs.filter((doc) => !doc.meta.content_language);
  const ledgerDocs = canonical.filter((doc) => doc.meta.type === 'tech.api.route.ledger');
  const contractDocs = canonical.filter((doc) => doc.meta.type === 'tech.api.contract');
  const routeFiles = new Set(routes.map((route) => route.file));
  const manualLedger = ledgerDocs.find((doc) => doc.meta.denominator === 'manual');
  const summary = { denominator: routes.length ? 'static' : (manualLedger ? 'manual' : 'none'), httpRoutes: routes.length, ledgerDocuments: ledgerDocs.length, ledgerRows: 0, contractEntries: 0, knownGaps: 0, uncoveredRouteFiles: routeFiles.size };

  if (!routes.length && !ledgerDocs.length && !contractDocs.length) {
    const suspects = walk(root).filter((file) => /(?:controllers?|routes?|handlers?|endpoints?)\.[\w]+$/i.test(file));
    if (suspects.length) warnings.push(`静态路由 0 条但存在 ${suspects.length} 个疑似入口文件（框架未被引擎识别或路由为动态注册）：需要人工建立 tech/contracts/route-ledger.md 并声明 denominator: manual；确认项目无 HTTP 入口可忽略本告警`);
    return { errors, warnings, summary };
  }

  if (!ledgerDocs.length) errors.push(`必产物缺失: tech/contracts/route-ledger.md —— 静态扫描${routes.length ? `发现 ${routes.length} 条 HTTP 路由` : '为 0 条但已有契约页'}，但没有路由台账（接口分母）`);
  const ledgerRows = [];
  for (const doc of ledgerDocs) {
    for (const line of doc.body.split('\n')) {
      const cells = line.trim().match(/^\|(.+)\|$/);
      if (!cells) continue;
      const columns = cells[1].split('|').map((cell) => cell.trim());
      if (columns.length < 4 || !HTTP_METHOD_IN_TEXT.test(columns[0]) || /^:?-{2,}/.test(columns[1])) continue;
      ledgerRows.push({ doc: doc.path, method: columns[0], path: columns[1], status: columns[columns.length - 1] });
    }
  }
  summary.ledgerRows = ledgerRows.length;
  if (ledgerDocs.length && routes.length && ledgerRows.length !== routes.length) {
    errors.push(`路由台账不完整: tech/contracts/route-ledger.md 记录 ${ledgerRows.length} 条，静态扫描到 ${routes.length} 条 HTTP 路由（差 ${Math.abs(routes.length - ledgerRows.length)}，抽样或按域汇总不能替代逐条枚举）`);
  }
  if (ledgerDocs.length && !routes.length && !manualLedger) {
    errors.push(`${ledgerDocs[0].path}: 静态路由为 0 条（框架未被识别或路由动态注册），台账必须声明 denominator: manual 并逐条人工登记，否则分母不可信`);
  }

  const entries = [];
  for (const doc of contractDocs) {
    for (const found of contractEntries(doc)) entries.push({ doc: doc.path, ...found });
  }
  summary.contractEntries = entries.length;
  for (const doc of contractDocs) {
    const declared = Number(doc.meta.entry_count);
    const own = entries.filter((entry) => entry.doc === doc.path).length;
    if (!Number.isFinite(declared)) { errors.push(`${doc.path}: 契约页必须声明 entry_count（等于本页接口小节数），当前缺失`); continue; }
    if (declared !== own) errors.push(`${doc.path}: entry_count=${declared} 与正文实际接口小节数 ${own} 不符`);
  }
  const knownGaps = ledgerRows.filter((row) => /待补|不适用/.test(row.status)).length;
  summary.knownGaps = knownGaps;

  if (!contractDocs.length) errors.push(`必产物缺失: 逐接口契约页 (type: tech.api.contract) —— 台账有 ${ledgerRows.length || routes.length} 条路由但接口条目为 0；按域分组汇总表不得标为契约页`);
  else if (entries.length + knownGaps !== ledgerRows.length && ledgerDocs.length) {
    errors.push(`接口契约缺口: 台账 ${ledgerRows.length} 条 / 契约条目 ${entries.length} 条 / 已标注待补或不适用 ${knownGaps} 条 —— 三者不闭合，缺口 ${ledgerRows.length - entries.length - knownGaps} 条未登记`);
  } else if (entries.length + knownGaps !== (ledgerDocs.length ? ledgerRows.length : routes.length) && !ledgerDocs.length) {
    errors.push(`接口契约缺口: 静态路由 ${routes.length} 条 / 契约条目 ${entries.length} 条 / 待补 0 条 —— 缺少台账，无法证明逐接口覆盖`);
  }

  if (ledgerDocs.length && entries.length) {
    const ledgerKeys = new Set(ledgerRows.filter((row) => !/[$]{/.test(row.path)).map((row) => normalizeEntry(row.method, row.path)));
    const entryKeys = new Set(entries.map((entry) => normalizeEntry(entry.method, entry.path)));
    const missingInContract = [...ledgerKeys].filter((key) => !entryKeys.has(key)).slice(0, 10);
    const extraInContract = [...entryKeys].filter((key) => !ledgerKeys.has(key)).slice(0, 10);
    if (missingInContract.length || extraInContract.length) {
      errors.push(`台账与契约路径集合不等: 契约缺少 ${missingInContract.length ? missingInContract.join(', ') : '无'}；契约多出（类级前缀未拼接或路由已删）${extraInContract.length ? extraInContract.join(', ') : '无'}`);
    }
  }

  const covered = new Set();
  for (const doc of [...ledgerDocs, ...contractDocs]) for (const source of parseSourceFiles(doc.meta.source_files)) covered.add(source);
  const uncovered = [...routeFiles].filter((file) => !covered.has(file));
  summary.uncoveredRouteFiles = uncovered.length;
  if (uncovered.length) errors.push(`接口覆盖缺口: ${uncovered.length} 个含路由的文件未被任何台账/契约页的 source_files 精确列出，例如 ${uncovered.slice(0, 3).join(', ')}`);

  for (const route of routes.filter((item) => item.unresolved).slice(0, 5)) warnings.push(`${route.file}:${route.line} 路径含配置占位符，台账需人工展开并标 待补`);
  if (knownGaps || uncovered.length) {
    for (const doc of [...ledgerDocs, ...contractDocs]) if (doc.meta.status === 'active') errors.push(`${doc.path}: 台账存在 ${knownGaps} 条待补、${uncovered.length} 个文件未覆盖，status 不得为 active，应设为 stale 并在完成报告中列为未完成项`);
  }
  return { errors, warnings, summary };
}

/** 部署证据与排障手册对账：证据文件为分母，缺页或未逐个覆盖即 error（Makefile/justfile 不计入分母）。 */
function deploymentEvidenceKind(relativePath) {
  const base = path.posix.basename(relativePath);
  const lower = base.toLowerCase();
  const parent = path.posix.dirname(relativePath);
  const dirs = parent === '.' || parent === '' ? '/' : `/${parent}/`;
  const inDirs = (names) => names.some((name) => dirs.includes(`/${name}/`));
  if (lower === 'dockerfile' || lower.startsWith('dockerfile.') || lower.endsWith('.dockerfile')) return 'image';
  if (/^(?:docker-compose|compose)[^/]*\.(?:ya?ml)$/i.test(base)) return 'compose';
  if (lower === 'chart.yaml' || lower === 'kustomization.yaml' || /^values[^/]*\.(?:ya?ml)$/i.test(base)) return 'helm';
  if (inDirs(['helm', 'charts'])) return /\.(?:ya?ml|tpl)$/i.test(base) ? 'helm' : null;
  if (/\.(?:ya?ml)$/i.test(base) && inDirs(['k8s', 'kubernetes', 'deploy', 'deployment', 'manifests'])) return 'k8s';
  if (/(^|\/)\.github\/workflows\/[^/]+\.ya?ml$/i.test(relativePath)) return 'ci';
  if (/(^|\/)\.circleci\/config\.ya?ml$/i.test(relativePath)) return 'ci';
  if (lower === '.gitlab-ci.yml' || lower === '.travis.yml' || lower === 'azure-pipelines.yml' || lower === 'jenkinsfile') return 'ci';
  if (lower === 'procfile' || lower === 'fly.toml' || lower === 'vercel.json' || lower === 'netlify.toml') return 'paas';
  if (/\.tf$/i.test(base)) return 'iac';
  return null;
}

function collectDeploymentEvidence(root) {
  const evidence = [];
  for (const file of walk(root)) {
    const kind = deploymentEvidenceKind(file);
    if (kind) evidence.push({ file, kind });
  }
  return evidence;
}

function checkOpsManuals(root, docs, routes, flowsCount) {
  const errors = [];
  const warnings = [];
  const canonical = docs.filter((doc) => !doc.meta.content_language);
  const evidence = collectDeploymentEvidence(root);
  const deploymentDocs = canonical.filter((doc) => doc.meta.type === 'manual.deployment.topology');
  const summary = { evidenceFiles: evidence.length, byKind: {}, deploymentDocuments: deploymentDocs.length, uncoveredEvidenceFiles: 0, troubleshootingRequired: false, troubleshootingDocuments: 0 };
  for (const item of evidence) summary.byKind[item.kind] = (summary.byKind[item.kind] || 0) + 1;
  if (evidence.length) {
    const sample = evidence.slice(0, 3).map((item) => item.file).join(', ');
    if (!deploymentDocs.length) {
      errors.push(`必产物缺失: manual/deployment.md —— 静态扫描发现 ${evidence.length} 个部署/发布证据文件（例如 ${sample}），但没有部署与运行拓扑页 (type: manual.deployment.topology)`);
    } else {
      const covered = new Set();
      for (const doc of deploymentDocs) for (const source of parseSourceFiles(doc.meta.source_files)) covered.add(source);
      const uncovered = evidence.filter((item) => !covered.has(item.file)).map((item) => item.file);
      summary.uncoveredEvidenceFiles = uncovered.length;
      if (uncovered.length) errors.push(`部署证据覆盖缺口: ${uncovered.length} 个证据文件未被部署页的 source_files 精确列出，例如 ${uncovered.slice(0, 3).join(', ')}（source_files 必须逐个穷举全部证据文件）`);
      for (const doc of deploymentDocs) if (uncovered.length && doc.meta.status === 'active') errors.push(`${doc.path}: 仍有 ${uncovered.length} 个证据文件未覆盖，status 不得为 active，应设为 stale`);
    }
  }
  const faqHasExperience = canonical.some((doc) => (doc.meta.type === 'manual.faq' || path.posix.basename(doc.path) === 'faq.md') && /^###\s+🧠/m.test(doc.body));
  const troubleshootingDocs = canonical.filter((doc) => doc.meta.type === 'manual.troubleshooting');
  summary.troubleshootingRequired = routes.length > 0 || flowsCount > 0 || faqHasExperience;
  summary.troubleshootingDocuments = troubleshootingDocs.length;
  if (summary.troubleshootingRequired && !troubleshootingDocs.length) {
    errors.push(`必产物缺失: manual/troubleshooting.md —— 触发条件命中（静态 HTTP 路由 ${routes.length} 条 / service-map 流程 ${flowsCount} 条${faqHasExperience ? ' / FAQ 含「🧠 经验沉淀」条目' : ''}），但缺少故障排查手册 (type: manual.troubleshooting)`);
  }
  return { errors, warnings, summary };
}

function validate(root) {
  const errors = []; const warnings = [];
  const sourcePaths = new Set(walk(root));
  const docs = scanKnowledgeDocs(root);
  const isIndexDoc = (doc) => path.posix.basename(doc.path) === 'INDEX.md' || Boolean(doc.meta.index_version);
  for (const doc of docs) {
    if (isIndexDoc(doc)) {
      for (const required of ['index_version', 'project_name', 'last_updated']) if (!doc.meta[required]) errors.push(`${doc.path}: INDEX frontmatter missing ${required}`);
    } else {
      for (const required of ['uuid', 'type', 'title', 'source_files', 'last_updated', 'status']) if (!doc.meta[required]) errors.push(`${doc.path}: missing frontmatter ${required}`);
    }
    for (const source of parseSourceFiles(doc.meta.source_files)) {
      const gitEvidence = doc.meta.type === 'manual.repository.history' && /^\.git\/(HEAD|refs\/heads\/[^/]+)$/.test(source);
      if (!gitEvidence && !sourcePaths.has(source)) warnings.push(`${doc.path}: source file does not exist or is excluded: ${source}`);
      if (['tech.api.contract', 'tech.api.route.ledger'].includes(doc.meta.type) && (/[*?]/.test(source) || source.endsWith('/'))) errors.push(`${doc.path}: 接口页 source_files 必须是精确文件路径（当前 "${source}" 为通配/目录，会让 diff 漏判受影响页）`);
    }
    const mermaidStarts = (doc.body.match(/```mermaid\s*$/gm) || []).length;
    const fencedBlocks = (doc.body.match(/^```\s*$/gm) || []).length;
    if (mermaidStarts > fencedBlocks) errors.push(`${doc.path}: unclosed Mermaid fence`);
    const links = [...doc.body.matchAll(/\[[^\]]+\]\(([^)#]+)(?:#[^)]+)?\)/g)].map((m) => m[1]);
    for (const link of links) if (!/^(https?:|mailto:)/.test(link)) {
      const linked = path.resolve(path.dirname(path.join(root, doc.path)), link);
      if (!fs.existsSync(linked)) warnings.push(`${doc.path}: broken local link: ${link}`);
    }
    if (/(?:AKIA[0-9A-Z]{16}|-----BEGIN (?:RSA |EC )?PRIVATE KEY-----)/.test(doc.body)) errors.push(`${doc.path}: possible secret in knowledge document`);
  }
  const canonicalDocs = docs.filter((doc) => !doc.meta.content_language && !isIndexDoc(doc));
  const titleIndex = new Map();
  for (const doc of canonicalDocs) {
    if (!doc.meta.title) continue;
    titleIndex.set(doc.meta.title, (titleIndex.get(doc.meta.title) || []).concat(doc));
  }
  for (const [title, list] of titleIndex) if (list.length > 1) warnings.push(`标题重复: "${title}" 出现在 ${list.map((doc) => doc.path).join(', ')}（parent 层级与 INDEX 导航会歧义）`);
  for (const doc of canonicalDocs) {
    if (!doc.meta.parent) continue;
    if (doc.meta.parent === doc.meta.title) { errors.push(`${doc.path}: parent 不得指向自身标题（${doc.meta.title}）`); continue; }
    const parentDoc = titleIndex.get(doc.meta.parent) && titleIndex.get(doc.meta.parent)[0];
    if (!parentDoc) { errors.push(`${doc.path}: parent "${doc.meta.parent}" 在主树中找不到对应标题（父页必须真实存在，禁止隐式目录页）`); continue; }
    const visited = new Set([doc.path]);
    let cursor = parentDoc;
    while (cursor) {
      if (visited.has(cursor.path)) { errors.push(`${doc.path}: parent 层级成环，回到已访问页面 ${cursor.path}`); break; }
      visited.add(cursor.path);
      const next = cursor.meta.parent && titleIndex.get(cursor.meta.parent);
      cursor = next ? next[0] : null;
    }
  }
  const mapFile = serviceMapPath(root);
  let flowsCount = 0;
  if (fs.existsSync(mapFile)) {
    try {
      const map = JSON.parse(fs.readFileSync(mapFile, 'utf8'));
      flowsCount = Array.isArray(map.flows) ? map.flows.length : 0;
      const allowed = new Set(['discovered', 'partial', 'code_confirmed', 'runtime_verified', 'confirmed']);
      for (const flow of Array.isArray(map.flows) ? map.flows : []) {
        if (!allowed.has(flow.status)) errors.push(`${toPosix(path.relative(root, mapFile))}: unsupported flow status ${flow.status}`);
        const steps = Array.isArray(flow.steps) ? flow.steps : [];
        const allEvidence = [flow.trigger, ...steps].every((step) => step && (typeof step.evidence === 'string' ? step.evidence.trim() : Array.isArray(step.evidence) && step.evidence.length));
        const unresolved = [flow.trigger, ...steps].some((step) => /待确认|待联调|unknown|todo/i.test(String(step && step.label)));
        if ((flow.status === 'confirmed' || flow.status === 'code_confirmed' || flow.status === 'runtime_verified') && (!allEvidence || unresolved)) {
          warnings.push(`${toPosix(path.relative(root, mapFile))}: flow ${flow.name || 'unnamed'} is marked ${flow.status} but contains missing evidence or unresolved steps; use partial/discovered until verified`);
        }
      }
    } catch (error) { errors.push(`${toPosix(path.relative(root, mapFile))}: invalid JSON (${error.message})`); }
  }
  const state = gitState(root);
  const historyDocs = docs.filter((doc) => doc.meta.type === 'manual.repository.history' && !doc.meta.content_language);
  for (const doc of historyDocs) {
    if (!doc.meta.git_state) errors.push(`${doc.path}: 必须声明 git_state（ok / no-commits / no-git），与 manifest.gitState 对应`);
    else if (doc.meta.git_state !== state) errors.push(`${doc.path}: git_state 声明为 "${doc.meta.git_state}"，引擎实测为 "${state}"`);
    if (state !== 'ok' && doc.meta.status === 'active') errors.push(`${doc.path}: Git 上下文不可用（gitState=${state}），status 不得为 active；应设为 stale 并在缺口清单写明不可采集的事实与恢复条件`);
  }
  if (state !== 'ok' && !historyDocs.length) warnings.push(`gitState=${state} 且缺少 manual/repository-history.md：非 Git 或零提交时这一页仍为必产物，须以 git_state + status: stale 留痕降级，不得静默跳过`);

  const routes = collectHttpRoutes(root);
  const contract = checkContractCoverage(root, docs, routes);
  const translation = checkTranslations(docs);
  const ops = checkOpsManuals(root, docs, routes, flowsCount);
  errors.push(...contract.errors, ...translation.errors, ...ops.errors);
  warnings.push(...contract.warnings, ...translation.warnings, ...ops.warnings);
  return { checkedAt: now(), gitState: state, documents: docs.length, contract: contract.summary, translation: translation.summary, deployment: ops.summary, errors, warnings, valid: errors.length === 0 };
}

function buildCards(root, manifest) {
  const files = new Map(manifest.files.map((file) => [file.path, file.sha256]));
  return {
    schemaVersion: 2, generatedAt: now(), gitHead: manifest.git && manifest.git.head,
    cards: scanKnowledgeDocs(root).filter((doc) => doc.meta.kb_card && !doc.meta.kb_card.includes('{')).map((doc) => ({
      id: doc.meta.uuid, type: doc.meta.type, title: doc.meta.title, module: doc.meta.module || null,
      summary: doc.meta.kb_card, document: doc.path,
      provenance: parseSourceFiles(doc.meta.source_files).map((source) => ({ path: source, sha256: files.get(source) || null })),
    })),
  };
}

async function requestEmbeddings(input) {
  const endpoint = process.env.KNOWLEDGE_EMBEDDING_URL;
  const model = process.env.KNOWLEDGE_EMBEDDING_MODEL;
  if (!endpoint || !model) throw new Error('embed requires KNOWLEDGE_EMBEDDING_URL and KNOWLEDGE_EMBEDDING_MODEL (OpenAI-compatible /v1/embeddings endpoint)');
  const headers = { 'content-type': 'application/json' };
  if (process.env.KNOWLEDGE_EMBEDDING_API_KEY) headers.authorization = `Bearer ${process.env.KNOWLEDGE_EMBEDDING_API_KEY}`;
  const response = await fetch(endpoint, { method: 'POST', headers, body: JSON.stringify({ model, input }) });
  if (!response.ok) throw new Error(`embedding request failed: HTTP ${response.status}`);
  const payload = await response.json();
  if (!Array.isArray(payload.data) || payload.data.length !== input.length) throw new Error('embedding response does not match request size');
  return { model, vectors: payload.data.sort((left, right) => left.index - right.index).map((item) => item.embedding) };
}

async function buildEmbeddings(root) {
  const cards = JSON.parse(fs.readFileSync(cardsPath(root), 'utf8')).cards;
  const input = cards.map((card) => `${card.title}\n${card.summary}`);
  const result = await requestEmbeddings(input);
  return { schemaVersion: 1, generatedAt: now(), model: result.model, vectors: cards.map((card, index) => ({ id: card.id, document: card.document, provenance: card.provenance, embedding: result.vectors[index] })) };
}

function discoveredEntrypoints(manifest) {
  return manifest.files.flatMap((file) => file.entrypoints.map((entrypoint) => ({ ...entrypoint, source: file.path })));
}

function buildServiceMapTemplate(root, manifest) {
  const entrypoints = discoveredEntrypoints(manifest);
  return {
    schemaVersion: 1,
    service: { name: path.basename(root), application: '待确认', role: '待确认：该服务在应用中的职责', owns: [], doesNotOwn: [] },
    dependencies: [],
    flows: entrypoints.map((entrypoint) => ({
      name: `${entrypoint.kind}: ${entrypoint.value}`,
      status: 'discovered',
      trigger: { type: entrypoint.kind, label: entrypoint.value, evidence: `${entrypoint.source}:${entrypoint.line}` },
      steps: [{ type: 'service', label: '补充该入口的业务处理、外部调用与结果', evidence: [] }],
    })),
    notes: ['discovered 表示仅从代码识别到入口；跨服务关系和业务步骤需人工确认后将 status 改为 confirmed。'],
  };
}

function escapeHtml(value) {
  return String(value == null ? '' : value).replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
}

function flowPresentation(flow) {
  const chain = [flow.trigger || {}, ...(Array.isArray(flow.steps) ? flow.steps : [])];
  const evidenceComplete = chain.every((step) => typeof step.evidence === 'string' ? step.evidence.trim() : Array.isArray(step.evidence) && step.evidence.length);
  const unresolved = chain.some((step) => /待确认|待联调|unknown|todo/i.test(String(step.label || '')));
  if (flow.status === 'runtime_verified' && evidenceComplete && !unresolved) return { className: 'runtime_verified', label: '运行已验证' };
  if ((flow.status === 'code_confirmed' || flow.status === 'confirmed') && evidenceComplete && !unresolved) return { className: 'code_confirmed', label: '源码已确认' };
  if (flow.status === 'partial' || flow.status === 'code_confirmed' || flow.status === 'confirmed') return { className: 'partial', label: '部分确认' };
  return { className: 'discovered', label: '代码发现' };
}

function renderRuntimeHtml(root, manifest) {
  const mapFile = serviceMapPath(root);
  const map = fs.existsSync(mapFile) ? JSON.parse(fs.readFileSync(mapFile, 'utf8')) : buildServiceMapTemplate(root, manifest);
  const service = map.service || {};
  const dependencies = Array.isArray(map.dependencies) ? map.dependencies : [];
  const flows = Array.isArray(map.flows) ? map.flows : [];
  const list = (items) => items.length ? items.map((item) => `<li>${escapeHtml(item)}</li>`).join('') : '<li>待确认</li>';
  const dependencyHtml = dependencies.length ? dependencies.map((dependency) => `<li><strong>${escapeHtml(dependency.direction || '关联')}</strong> · ${escapeHtml(dependency.name)} <span>${escapeHtml(dependency.type || '接口')} / ${escapeHtml(dependency.status || 'discovered')}</span></li>`).join('') : '<li>未声明外部依赖</li>';
  const flowHtml = flows.length ? flows.map((flow) => {
    const trigger = flow.trigger || {};
    const steps = Array.isArray(flow.steps) ? flow.steps : [];
    const chain = [{ type: trigger.type || 'entry', label: trigger.label || flow.name, evidence: trigger.evidence }].concat(steps);
    const presentation = flowPresentation(flow);
    return `<section class="flow"><header><h2>${escapeHtml(flow.name || '未命名流程')}</h2><span class="status ${presentation.className}">${presentation.label}</span></header><div class="chain">${chain.map((step, index) => `<div class="node"><b>${escapeHtml(step.type || 'step')}</b><span>${escapeHtml(step.label)}</span>${step.evidence ? `<code>${escapeHtml(Array.isArray(step.evidence) ? step.evidence.join(', ') : step.evidence)}</code>` : ''}</div>${index < chain.length - 1 ? '<div class="arrow" aria-hidden="true">→</div>' : ''}`).join('')}</div></section>`;
  }).join('') : '<p class="empty">未发现可视化流程。</p>';
  const coverage = `${flows.length} 条流程 / ${discoveredEntrypoints(manifest).length} 个入口`;
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(service.name || path.basename(root))} 运行地图</title><style>:root{color-scheme:light dark;--bg:#f7f8fa;--card:#fff;--ink:#172033;--muted:#5f6b7a;--line:#d6dbe3;--accent:#2563eb;--ok:#087443;--warn:#a15c00}@media(prefers-color-scheme:dark){:root{--bg:#10141c;--card:#19212e;--ink:#eef3fb;--muted:#adbac9;--line:#344154;--accent:#80b4ff;--ok:#71d49d;--warn:#ffc36a}}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,-apple-system,sans-serif}.wrap{max-width:1180px;margin:auto;padding:32px 20px}header.top{display:flex;justify-content:space-between;gap:18px;align-items:start;border-bottom:1px solid var(--line);padding-bottom:22px}h1{font-size:28px;margin:0 0 5px}h2{font-size:17px;margin:0}p{margin:4px 0;color:var(--muted)}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:20px 0}.panel,.flow{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px}.panel h2{margin-bottom:8px}ul{margin:0;padding-left:18px}li{margin:5px 0}.dependencies{display:grid;grid-template-columns:1fr 1fr;gap:14px}.flow{margin:14px 0}.flow header{display:flex;justify-content:space-between;align-items:center}.chain{display:flex;align-items:stretch;gap:9px;overflow-x:auto;padding-top:14px}.node{min-width:175px;max-width:250px;border-left:4px solid var(--accent);background:color-mix(in srgb,var(--accent) 8%,transparent);padding:10px}.node b,.node span,.node code{display:block}.node b{font-size:12px;text-transform:uppercase;color:var(--muted)}.node code{font-size:11px;overflow-wrap:anywhere;color:var(--muted);margin-top:6px}.arrow{align-self:center;font-size:24px;color:var(--muted)}.status{font-size:12px;padding:2px 8px;border-radius:999px}.runtime_verified,.code_confirmed{color:var(--ok);background:color-mix(in srgb,var(--ok) 14%,transparent)}.partial,.discovered{color:var(--warn);background:color-mix(in srgb,var(--warn) 14%,transparent)}.empty{padding:20px}@media(max-width:680px){header.top,.meta,.dependencies{display:block}.meta .panel,.dependencies .panel{margin:12px 0}}</style></head><body><main class="wrap"><header class="top"><div><h1>${escapeHtml(service.name || path.basename(root))} · 服务运行地图</h1><p>${escapeHtml(service.application || '未标注应用')} / ${escapeHtml(service.role || '待确认服务定位')}</p></div><p>生成于 ${escapeHtml(now())}<br>${escapeHtml(coverage)}</p></header><section class="meta"><article class="panel"><h2>负责什么</h2><ul>${list(Array.isArray(service.owns) ? service.owns : [])}</ul></article><article class="panel"><h2>不负责什么</h2><ul>${list(Array.isArray(service.doesNotOwn) ? service.doesNotOwn : [])}</ul></article><article class="panel"><h2>外部依赖</h2><ul>${dependencyHtml}</ul></article></section><section aria-label="服务运行流程">${flowHtml}</section></main></body></html>`;
}

function languageInit(root, language, dryRun) {
  if (!/^[a-z]{2}(?:-[A-Z]{2})?$/.test(language || '')) throw new Error('language-init requires --language zh or en');
  const base = path.join(root, '.aisdd', 'knowledges');
  const target = path.join(base, language);
  if (!fs.existsSync(base)) throw new Error('knowledge directory not found; run init first');
  const copied = [];
  const visit = (dir, atBase) => fs.readdirSync(dir, { withFileTypes: true }).forEach((item) => {
    if (item.name === '.engine' || item.name === 'visualizations') return;
    if (atBase && new RegExp(`^[a-z]{2}(?:-[A-Z]{2})?$`).test(item.name) && fs.statSync(path.join(dir, item.name)).isDirectory()) return;
    const full = path.join(dir, item.name);
    if (item.isDirectory()) return visit(full, false);
    if (!item.isFile() || !item.name.endsWith('.md')) return;
    const relative = path.relative(base, full); const dest = path.join(target, relative);
    let body = fs.readFileSync(full, 'utf8');
    if (body.startsWith('---\n')) {
      const lines = body.replace(/^---\n/, `---\ncontent_language: ${language}\ntranslation_status: pending\nsource_document: ${toPosix(relative)}\n`).split('\n');
      const end = lines.indexOf('---', 1);
      if (end > 1) {
        let hasStatus = false;
        for (let index = 1; index < end; index += 1) {
          if (/^status:/.test(lines[index])) { lines[index] = 'status: stale'; hasStatus = true; }
          else if (/^uuid:/.test(lines[index])) lines[index] = `${lines[index]}-${language}`;
        }
        if (!hasStatus) lines.splice(end, 0, 'status: stale');
      }
      body = `${lines.join('\n')}\n`;
    }
    if (!dryRun) { fs.mkdirSync(path.dirname(dest), { recursive: true }); fs.writeFileSync(dest, body); }
    copied.push(toPosix(path.relative(root, dest)));
  });
  visit(base, true);
  return { language, copied, status: 'pending-translation' };
}

function exportWiki(root) {
  const docs = scanKnowledgeDocs(root).filter((doc) => !doc.path.includes('/visualizations/'));
  const nav = docs.map((doc) => `<li><a href="#${escapeHtml(doc.meta.uuid || doc.path)}">${escapeHtml(doc.meta.title || doc.path)}</a></li>`).join('');
  const pages = docs.map((doc) => `<article id="${escapeHtml(doc.meta.uuid || doc.path)}"><h2>${escapeHtml(doc.meta.title || doc.path)}</h2><p>${escapeHtml(doc.path)} · ${escapeHtml(doc.meta.status || 'unknown')}</p><pre>${escapeHtml(doc.body.replace(/^---[\s\S]*?---\s*/, ''))}</pre></article>`).join('');
  return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>知识库导出</title><style>body{font:15px/1.6 system-ui,sans-serif;max-width:1100px;margin:auto;padding:24px;color:#172033}nav{position:sticky;top:0;background:#fff;border-bottom:1px solid #ddd;padding:10px}nav ul{display:flex;gap:14px;flex-wrap:wrap;list-style:none;padding:0;margin:0}article{border-bottom:1px solid #ddd;padding:20px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f8fa;padding:16px}a{color:#1459bf}</style><h1>知识库导出</h1><nav><ul>${nav}</ul></nav>${pages}</html>`;
}

function installHook(root, force, dryRun) {
  const hook = path.join(root, '.git', 'hooks', 'pre-commit');
  if (!fs.existsSync(path.join(root, '.git'))) throw new Error('hook install requires a Git repository');
  if (fs.existsSync(hook) && !force) throw new Error(`hook already exists; use --force only after reviewing it: ${hook}`);
  const content = `#!/bin/sh\n# knowledge-engine quality gate; never rewrites knowledge documents\nnode .aisdd/bin/knowledge-engine.js validate .\n`;
  writeText(hook, content, dryRun);
  if (!dryRun) fs.chmodSync(hook, 0o755);
}

/**
 * 由 manifest 的 import 语句解析"文件 → 文件"边。
 * 只在依赖标识符末段能唯一命中（声明的符号名或同名文件）时建边，避免把标准库/三方包当项目邻居。
 */
function dependencyEdges(manifest) {
  const declared = new Map();
  for (const file of manifest.files) {
    const bucket = new Set();
    for (const symbol of file.symbols) bucket.add(symbol.name);
    const base = path.posix.basename(file.path).replace(/\.[^.]+$/, '');
    if (base) bucket.add(base);
    for (const key of bucket) {
      if (!declared.has(key)) declared.set(key, new Set());
      declared.get(key).add(file.path);
    }
  }
  const out = new Map(); const inn = new Map();
  const push = (index, from, edge) => { if (!index.has(from)) index.set(from, []); index.get(from).push(edge); };
  for (const file of manifest.files) {
    for (const dependency of file.dependencies) {
      const tail = String(dependency).split(/[./]/).filter(Boolean).pop();
      if (!tail) continue;
      const targets = [...(declared.get(tail) || [])].filter((target) => target !== file.path);
      if (targets.length !== 1) continue;
      push(out, file.path, { path: targets[0], via: dependency });
      push(inn, targets[0], { path: file.path, via: dependency });
    }
  }
  return { out, inn };
}

function search(root, query) {
  if (!query || !query.trim()) throw new Error('search requires --query <text>');
  const words = [...new Set(query.toLowerCase().split(/\s+/).filter(Boolean))];
  const manifest = loadManifest(root);
  const cards = fs.existsSync(cardsPath(root)) ? JSON.parse(fs.readFileSync(cardsPath(root), 'utf8')).cards : [];
  const score = (text) => words.reduce((total, word) => total + (text.toLowerCase().includes(word) ? 1 : 0), 0);
  const code = manifest.files.map((file) => {
    const pathScore = score(file.path) * 2;
    const symbolMatches = file.symbols.filter((symbol) => score(symbol.name) > 0);
    const entrypointMatches = file.entrypoints.filter((entrypoint) => score(`${entrypoint.kind} ${entrypoint.value}`) > 0);
    const dependencyMatches = file.dependencies.filter((dependency) => score(dependency) > 0);
    return { path: file.path, score: pathScore + symbolMatches.length * 3 + entrypointMatches.length * 3 + dependencyMatches.length, symbols: symbolMatches, entrypoints: entrypointMatches, dependencies: dependencyMatches, sha256: file.sha256 };
  }).filter((item) => item.score > 0).sort((left, right) => right.score - left.score).slice(0, 20);
  const knowledgeCards = cards.map((card) => ({ ...card, score: score(`${card.title} ${card.summary} ${card.module || ''}`) * 4 }))
    .filter((card) => card.score > 0).sort((left, right) => right.score - left.score).slice(0, 20);
  const edges = dependencyEdges(manifest);
  const filesByPath = new Map(manifest.files.map((file) => [file.path, file]));
  const direct = new Set(code.map((item) => item.path));
  const relatedMap = new Map();
  for (const seed of code.slice(0, 10)) {
    const directions = [[edges.out.get(seed.path) || [], 'imports'], [edges.inn.get(seed.path) || [], 'imported-by']];
    for (const [list, direction] of directions) for (const edge of list) {
      if (direct.has(edge.path)) continue;
      const candidate = { path: edge.path, direction, via: edge.via, from: seed.path, score: Math.ceil(seed.score / 2) };
      const existing = relatedMap.get(edge.path);
      if (!existing || candidate.score > existing.score) relatedMap.set(edge.path, candidate);
    }
  }
  const related = [...relatedMap.values()].sort((left, right) => right.score - left.score || left.path.localeCompare(right.path)).slice(0, 20)
    .map((item) => ({ ...item, symbols: (filesByPath.get(item.path).symbols || []).slice(0, 8), entrypoints: (filesByPath.get(item.path).entrypoints || []).slice(0, 8), sha256: filesByPath.get(item.path).sha256 }));
  return { query, generatedAt: now(), retrieval: ['path-keyword', 'symbols', 'entrypoints', 'dependencies', 'knowledge-cards', 'dependency-graph-1hop'], graph: { edges: edges.out.size + edges.inn.size, seedsConsidered: Math.min(code.length, 10), expanded: related.length }, code, related, knowledgeCards };
}

function usage() {
  process.stdout.write(`Usage: node tools/knowledge-engine.js <command> [project-root] [--dry-run]\n\nCommands:\n  scan           create source manifest and facts\n  diff           report source changes and affected knowledge pages\n  validate       check frontmatter, evidence paths, links and Mermaid fences\n  cards          materialize independent knowledge cards from kb_card metadata\n  embed          build optional semantic embeddings from cards (explicit provider config)\n  search         explainable local retrieval + 1-hop dependency graph; requires --query <text>\n  profile/render service positioning and standalone runtime HTML\n  language-init  copy the main tree into a pending language tree (status stale, suffixed uuid); requires --language en|zh\n  export         create an offline, single-file static Wiki HTML\n  hook           install non-destructive pre-commit validation; use --force to replace\n  update         run scan + diff + validate + cards (safe: never rewrites prose)\n`);
}

async function main() {
  let args;
  try { args = parseArgs(process.argv); } catch (error) { fail(error.message); return; }
  try {
    if (args.command === 'help' || args.command === '--help' || args.command === '-h') return usage();
    if (args.command === 'scan') {
      const manifest = buildManifest(args.root);
      if (args.dryRun) { process.stdout.write(`${JSON.stringify(manifest, null, 2)}\n`); return; }
      return writeJson(args.out ? path.resolve(args.root, args.out) : manifestPath(args.root), manifest, false);
    }
    if (args.command === 'diff') {
      const report = diffManifest(loadManifest(args.root), buildManifest(args.root));
      if (args.dryRun) { process.stdout.write(`${JSON.stringify(report, null, 2)}\n`); return; }
      writeJson(args.out ? path.resolve(args.root, args.out) : impactPath(args.root), report, false); return;
    }
    if (args.command === 'validate') {
      const result = validate(args.root); process.stdout.write(`${JSON.stringify(result, null, 2)}\n`); if (!result.valid) process.exitCode = 2; return;
    }
    if (args.command === 'cards') return writeJson(args.out ? path.resolve(args.root, args.out) : cardsPath(args.root), buildCards(args.root, loadManifest(args.root)), args.dryRun);
    if (args.command === 'embed') {
      if (args.dryRun) return writeJson(args.out ? path.resolve(args.root, args.out) : embeddingsPath(args.root), { status: 'would-request-embeddings' }, true);
      return writeJson(args.out ? path.resolve(args.root, args.out) : embeddingsPath(args.root), await buildEmbeddings(args.root), false);
    }
    if (args.command === 'search') { process.stdout.write(`${JSON.stringify(search(args.root, args.query), null, 2)}\n`); return; }
    if (args.command === 'profile') {
      const target = args.out ? path.resolve(args.root, args.out) : serviceMapPath(args.root);
      if (fs.existsSync(target) && !args.dryRun) throw new Error(`profile already exists; edit it or choose --out: ${target}`);
      return writeJson(target, buildServiceMapTemplate(args.root, loadManifest(args.root)), args.dryRun);
    }
    if (args.command === 'render') return writeText(args.out ? path.resolve(args.root, args.out) : runtimeHtmlPath(args.root), renderRuntimeHtml(args.root, loadManifest(args.root)), args.dryRun);
    if (args.command === 'language-init') { process.stdout.write(`${JSON.stringify(languageInit(args.root, args.language, args.dryRun), null, 2)}\n`); return; }
    if (args.command === 'export') return writeText(args.out ? path.resolve(args.root, args.out) : path.join(args.root, '.aisdd', 'knowledges', 'export.html'), exportWiki(args.root), args.dryRun);
    if (args.command === 'hook') return installHook(args.root, args.force, args.dryRun);
    if (args.command === 'update') {
      const previous = fs.existsSync(manifestPath(args.root)) ? loadManifest(args.root) : null;
      const current = buildManifest(args.root);
      const impact = previous ? diffManifest(previous, current) : null;
      if (impact) writeJson(impactPath(args.root), impact, args.dryRun);
      writeJson(manifestPath(args.root), current, args.dryRun);
      const result = validate(args.root); process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
      writeJson(cardsPath(args.root), buildCards(args.root, current), args.dryRun);
      writeJson(updateRecordPath(args.root), {
        schemaVersion: 1, generatedAt: now(), gitState: current.gitState, git: current.git,
        scope: current.scope, validation: result, impact,
        note: 'Derived local run record. It proves scan/validation state, not runtime behavior.',
      }, args.dryRun);
      if (!result.valid) process.exitCode = 2;
      return;
    }
    fail(`unknown command: ${args.command}`); usage();
  } catch (error) { fail(error.stack || error.message); }
}
main().catch((error) => fail(error.stack || error.message));
